'use strict';
const fs=require('fs'),crypto=require('crypto');
const {chromium}=require('/workspace/gridex-krypkorning-run-20261111/node_modules/playwright');
const root='/workspace/gridex-task-recovery-runtime-evidence-20261112';
const cfg=JSON.parse(fs.readFileSync(root+'/runtime-input.private.json','utf8'));
if((fs.statSync(root+'/runtime-input.private.json').mode&0o077)!==0)throw Error('PRIVATE_CONFIG_0600_REQUIRED');
for(const u of[cfg.appUrl,cfg.apiUrl])if(new URL(u).hostname!=='127.0.0.1')throw Error('LOOPBACK_ONLY');
const hash=x=>crypto.createHash('sha256').update(x).digest('hex');
const canonical=x=>Array.isArray(x)?x.map(canonical):x&&typeof x==='object'?Object.fromEntries(Object.keys(x).sort().map(k=>[k,canonical(x[k])])):x;
const rowHash=x=>hash(JSON.stringify(canonical(x)));
const tag=crypto.randomBytes(5).toString('hex');
const cases=[{name:cfg.recoverySite.site_name,area:'SE3',facility:cfg.recoverySite.facility_id,street:cfg.recoverySite.street,postal:cfg.recoverySite.postal_code,city:cfg.recoverySite.city},{name:'Kryp SITE01.04 SE4 '+tag,area:'SE4',facility:'735999999990000045',street:'Simuleringsgatan 41',postal:'21122',city:'Malmö'}];
const result={kind:'NORMAL_SITE01_04_RECOVERY_EDIT_EXISTING_A_PLUS_NEW_B',scenarioId:'SITE01.04',sourceReceipt:cfg.sourceReceipt,recoveredExistingSiteId:cfg.recoverySite.id,originalPartialCreationAuditNotBackfilled:true,plannedInputs:cases,actorId:cfg.actor.id,companyId:cfg.companyId,customerId:cfg.customerId,steps:[],httpPosts:[],sites:[],startedAt:new Date().toISOString(),scope:'MANUAL_UNVERIFIED_CANDIDATES_NOT_MARKET_OR_BILLING_ACCEPTANCE'};
const write=()=>fs.writeFileSync(root+'/site04-original.safe.json',JSON.stringify(result,null,2),{mode:0o600});
function checkSecrets(body){if([cfg.serviceKey,cfg.jwtSecret,cfg.actor.password].some(v=>v&&body.includes(v)))throw Error('KNOWN_SECRET_RESPONSE_LEAK')}
async function read(table,query){const r=await fetch(cfg.apiUrl+'/rest/v1/'+table+'?'+query,{headers:{apikey:cfg.serviceKey,Authorization:'Bearer '+cfg.serviceKey}});if(!r.ok)throw Error('READ_ONLY_READBACK_'+r.status);return await r.json()}
const readSites=()=>read('customer_sites','select=*&company_id=eq.'+cfg.companyId+'&customer_id=eq.'+cfg.customerId);
const project=s=>({id:s.id,company_id:s.company_id,customer_id:s.customer_id,site_name:s.site_name,facility_id:s.facility_id,status:s.status,is_active:s.is_active,created_by:s.created_by,updated_by:s.updated_by,address_hash:s.address_hash,address_status:s.address_status,facility_data_status:s.facility_data_status,resolution_status:s.resolution_status,grid_owner_id:s.grid_owner_id,price_area_code:s.price_area_code,metadata:{address_candidate_metadata:{manual_price_area_hint:s.metadata?.address_candidate_metadata?.manual_price_area_hint,source:s.metadata?.address_candidate_metadata?.source},claimed_price_area_code:s.metadata?.claimed_price_area_code},fullMetadataSha256:rowHash(s.metadata??{})});
let browser,context,page,activeIntent;
async function form(editId){const r=await page.goto(cfg.appUrl+'/admin/customers/'+cfg.customerId+(editId?'?editSite='+editId:'?tab=sites'),{waitUntil:'domcontentloaded',timeout:180000});const f=page.locator('form').filter({has:page.locator('input[name=site_name]')});result.steps.push({kind:'NORMAL_UI_FORM_READ',editId:editId??null,status:r.status(),formCount:await f.count()});write();if(r.status()!==200||await f.count()!==1)throw Error('NORMAL_FORM_UNAVAILABLE');const d=f.locator('xpath=ancestor::details[1]');if(await d.count()&&await d.getAttribute('open')===null)await d.locator('summary').click();const options=await f.locator('[name=price_area_code] option').evaluateAll(xs=>xs.map(x=>x.value));result.steps.push({kind:'NORMAL_OPTIONS_BEFORE_POST',values:options});write();if(!['SE1','SE2','SE3','SE4'].every(x=>options.includes(x)))throw Error('NORMAL_REFERENCE_OPTIONS_MISSING');const actualId=await f.locator('input[name=id]').inputValue();if(actualId!==(editId??''))throw Error('NORMAL_FORM_ID_MISMATCH');return f}
async function fill(f,v){for(const[k,value]of Object.entries({site_name:v.name,facility_id:v.facility,street:v.street,postal_code:v.postal,city:v.city,country:'SE'}))await f.locator('[name='+k+']').fill(value);await f.locator('[name=status]').selectOption('draft');await f.locator('[name=site_flow_type]').selectOption('switch');await f.locator('[name=price_area_code]').selectOption(v.area)}
async function post(f,intent){activeIntent=intent;result.steps.push({kind:'POST_INTENT',...intent});write();let response;try{[response]=await Promise.all([page.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).pathname==='/admin/customers/'+cfg.customerId,{timeout:120000}),f.locator('button[type=submit]').click()]);result.steps.push({kind:'POST_RESPONSE_STATUS',intent:intent.kind,status:response.status()});write();try{const body=await response.text();checkSecrets(body);result.steps.push({kind:'POST_BODY_HASH',intent:intent.kind,sha256:hash(body),bytes:Buffer.byteLength(body)});write()}catch(e){if(e.message==='KNOWN_SECRET_RESPONSE_LEAK')throw e;result.steps.push({kind:'POST_BODY_UNAVAILABLE_STATUS_ALREADY_RETAINED',intent:intent.kind,errorClass:e.name});write()}return response.status()}finally{const rows=await readSites();result.steps.push({kind:'POST_COMMIT_READBACK',intent:intent.kind,matchingRows:rows.filter(s=>intent.siteId?s.id===intent.siteId:s.site_name===intent.name).map(project),allSelectedCustomerSiteCount:rows.length});write();activeIntent=null}}
function assertCandidate(s,area){if(s.company_id!==cfg.companyId||s.customer_id!==cfg.customerId||s.created_by!==cfg.actor.id||s.updated_by!==cfg.actor.id)throw Error('SITE_OWNER_OR_ACTOR_MISMATCH');if(s.status!=='draft')throw Error('SITE_DRAFT_STATUS_CHANGED');if(s.price_area_code!==null||s.grid_owner_id!==null)throw Error('MANUAL_HINT_BECAME_OPERATIONAL');if(s.metadata?.address_candidate_metadata?.manual_price_area_hint!==area)throw Error('MANUAL_HINT_NOT_PRESERVED');if(s.address_status==='verified'||s.facility_data_status==='verified')throw Error('MANUAL_HINT_VERIFIED')}
(async()=>{try{write();const before=await readSites();if(!before.some(s=>s.id===cfg.recoverySite.id&&s.company_id===cfg.companyId&&s.customer_id===cfg.customerId))throw Error('RECOVERY_SITE_NOT_OWNED');if(before.some(s=>s.facility_id===cases[1].facility))throw Error('B_ALREADY_EXISTS_NO_CREATE_RETRY');const old=new Map(before.map(s=>[s.id,rowHash(s)]));result.beforeSites=before.map(s=>({id:s.id,sha256:old.get(s.id)}));write();browser=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox']});context=await browser.newContext();page=await context.newPage();page.on('response',r=>{if(r.request().method()==='POST'&&new URL(r.url()).pathname==='/admin/customers/'+cfg.customerId){result.httpPosts.push({kind:activeIntent?.kind??'UNKNOWN_CAPTURE_INTENT',path:new URL(r.url()).pathname,status:r.status(),at:new Date().toISOString()});write()}});await page.goto(cfg.appUrl+'/login',{waitUntil:'domcontentloaded',timeout:180000});await page.locator('input[name=email]').fill(cfg.actor.email);await page.locator('input[name=password]').fill(cfg.actor.password);await Promise.all([page.waitForURL(u=>u.pathname!='/login',{timeout:120000}),page.locator('button[type=submit]').click()]);result.normalUiLogin=true;const body=await page.content();checkSecrets(body);result.verifiedPlatformPresentation=body.includes('Plattformsöversikt')&&body.includes('Gridex Platform Operations');write();if(!result.verifiedPlatformPresentation)throw Error('PLATFORM_PRESENTATION_NOT_REACHED');for(const[index,v]of cases.entries()){const recovery=index===0;const f=await form(recovery?cfg.recoverySite.id:undefined);await fill(f,v);const status=await post(f,{kind:recovery?'RECOVERY_EDIT_A':'CREATE_B_SE4',name:v.name,siteId:recovery?cfg.recoverySite.id:null});const rows=await readSites(),own=rows.filter(s=>s.site_name===v.name);if(status!==200)throw Error('POST_HTTP_'+status+'_STOP_NO_CREATE_RETRY');if(own.length!==1)throw Error('CREATE_COMMIT_COUNT_NOT_ONE');const s=own[0];if(recovery&&s.id!==cfg.recoverySite.id)throw Error('RECOVERY_ID_CHANGED');assertCandidate(s,v.area);const audit=await read('audit_logs','select=id,actor_user_id,company_id,entity_id,action&company_id=eq.'+cfg.companyId+'&entity_id=eq.'+s.id+'&action=eq.'+(recovery?'customer_site_updated':'customer_site_created'));if(!audit.some(a=>a.actor_user_id===cfg.actor.id))throw Error('NORMAL_AUDIT_ACTOR_NOT_CONFIRMED');const tasks=await read('customer_operation_tasks','select=id,company_id,customer_id,site_id,status,created_by,updated_by&company_id=eq.'+cfg.companyId+'&site_id=eq.'+s.id);if(!tasks.length||!tasks.every(t=>t.company_id===cfg.companyId&&t.customer_id===cfg.customerId&&t.site_id===s.id&&t.created_by===cfg.actor.id))throw Error('TASK_COMPANY_OR_ACTOR_NOT_CONFIRMED');result.sites.push(project(s));result.steps.push({kind:'UI_ACTION_AUDIT_AND_TASK_READBACK',siteId:s.id,recovery,audit,tasks});write();if(!before.filter(b=>b.id!==cfg.recoverySite.id).every(b=>rows.some(s=>s.id===b.id&&rowHash(s)===old.get(b.id))))throw Error('PREEXISTING_SITE_CHANGED')}
const[A,B]=result.sites;result.distinctIdsAndAddressHashes=A.id!==B.id&&A.address_hash!==B.address_hash;write();if(!result.distinctIdsAndAddressHashes)throw Error('NEW_SITES_NOT_DISTINCT');const pre=await readSites();if(pre.length!==before.length+1)throw Error('UNEXPECTED_CREATE_COUNT');const bHash=rowHash(pre.find(s=>s.id===B.id));let f=await form(A.id);await fill(f,cases[0]);let status=await post(f,{kind:'SAME_ID_EDIT_REPLAY',name:cases[0].name,siteId:A.id});let rows=await readSites();if(status!==200)throw Error('EDIT_POST_HTTP_'+status);result.editReplay={sameId:rows.some(s=>s.id===A.id),countBefore:pre.length,countAfter:rows.length,secondSiteUnchanged:rowHash(rows.find(s=>s.id===B.id))===bHash};assertCandidate(rows.find(s=>s.id===A.id),'SE3');write();if(!result.editReplay.sameId||result.editReplay.countBefore!==result.editReplay.countAfter||!result.editReplay.secondSiteUnchanged)throw Error('ID_BOUND_REPLAY_ISOLATION_FAILED');f=await form(A.id);const renamedA=cases[0].name+' (kryp edit '+tag+')';await fill(f,{...cases[0],name:renamedA});status=await post(f,{kind:'CHANGE_ONLY_A_NAME',name:renamedA,siteId:A.id});rows=await readSites();if(status!==200)throw Error('EDIT_CHANGE_POST_HTTP_'+status);result.singleSiteChange={first:project(rows.find(s=>s.id===A.id)),second:project(rows.find(s=>s.id===B.id)),secondSiteUnchanged:rowHash(rows.find(s=>s.id===B.id))===bHash};write();assertCandidate(rows.find(s=>s.id===A.id),'SE3');if(rows.find(s=>s.id===A.id).site_name!==renamedA)throw Error('A_NAME_UPDATE_NOT_CONFIRMED');if(!result.singleSiteChange.secondSiteUnchanged)throw Error('SIBLING_SITE_CHANGED');if(rows.length!==pre.length)throw Error('EDIT_CREATED_EXTRA_SITE');result.oracle='MET_LOCAL_MANUAL_CANDIDATE_INTAKE_AND_ID_BOUND_EDIT_ISOLATION';result.state='TERMINAL';write()}catch(e){result.state='STOPPED_AT_ACTUAL_BOUNDARY';result.errorClass=e.name;result.safeErrorCode=/^[A-Z_0-9]+$/.test(String(e.message))?e.message:'CAPTURE_ERROR_DETAILS_PRIVATE';fs.writeFileSync(root+'/capture-error.private.log',String(e.stack??e),{mode:0o600});write();process.exitCode=1}finally{if(page){try{await page.goto(cfg.appUrl+'/logout',{waitUntil:'domcontentloaded',timeout:60000});await Promise.all([page.waitForURL(u=>u.pathname==='/login'),page.locator('form[action="/logout"] button[type=submit]').click()]);result.normalUiPostLogout=true;write()}catch(e){result.normalLogoutErrorClass=e.name;write()}}await context?.close();await browser?.close();result.finishedAt=new Date().toISOString();write()}})();
